program='''def transform(grid):
    n = len(grid)
    m = len(grid[0])
    source = [row[:] for row in grid]
    result = [row[:] for row in source]

    def orbit(start_r, start_c):
        seen = {(start_r, start_c)}
        stack = [(start_r, start_c)]
        while stack:
            r, c = stack.pop()
            candidates = []
            if c < n and r < m:
                candidates.append((c, r))
            if 2 <= r < n and n + 1 - r < n:
                candidates.append((n + 1 - r, c))
            for point in candidates:
                rr, cc = point
                if 0 <= rr < n and 0 <= cc < m and point not in seen:
                    seen.add(point)
                    stack.append(point)
        return seen

    for r in range(n):
        for c in range(m):
            if source[r][c] != 6:
                continue
            values = {source[rr][cc] for rr, cc in orbit(r, c) if source[rr][cc] != 6}
            if len(values) == 1:
                result[r][c] = next(iter(values))
    return result
'''
